const initialMessage = $('Aggregate').item.json.message.join(",");
let contextMessage = "";
try {
  contextMessage = $('Obtiene mensaje contexto').item.json.mensaje || "";
} catch (e) {
  contextMessage = "";
}

let productCatalog = "";
try {
  productCatalog = $('Obtiene nombre producto catalogo').item.json.producto || "";
} catch (e) {
  productCatalog = "";
}

return {
  message: `${initialMessage} ${contextMessage} ${productCatalog}`.trim().replace(/\s+/g, ' ')
};

const tokenUsage = JSON.parse($('Agente Coordinador').item.json.output);
const now = Date.now();

return {
  process_id: "coordinating_agent",
  model_name: tokenUsage.model_name,
  prompt_tokens: tokenUsage.prompt_tokens,
  completion_tokens: tokenUsage.completion_tokens,
  total_tokens: tokenUsage.total_tokens,
  ai_response: tokenUsage.ai_response,
  completed_at: now,
  created_at: now,
  environment: 'ist'
};

const init = $('get_start_operation').first().json.value;
const end = $('get_end_operation').first().json.value;
const now = $now.hour
if (now >= init && now <= end){
  return [{ json: { open: true, hora_actual: now } }];
} else {
  return [{ json: { open: false, hora_actual: now } }];
}
